import {ANALYSIS_MODULES,moduleById,analysisData,pairOverlap} from './v15-analysis-model.mjs';
import {checkedNav,outsideSample} from './v14-compute.mjs';
import {esc as h,icon,metric,formula,empty,percent as p,money} from './v15-ui.mjs';
const button=(act,label,id='',on=false)=>`<button type="button" class="v15-button ${on?'is-selected':''}" data-act="${act}" data-id="${h(id)}">${h(label)}</button>`;
export function moduleDirectory(active='overlap',guide=false){return `<div class="v15-directory" aria-label="分析模块">${ANALYSIS_MODULES.map(g=>`<section class="v15-module-group"><h2>${h(g.name)}</h2><div>${g.items.map(([id,name,symbol,desc])=>`<button type="button" data-act="${guide?'guide-analysis':'analysis-module'}" data-id="${id}" class="v15-module-link ${active===id&&!guide?'is-active':''}" aria-pressed="${active===id&&!guide}">${icon(symbol)}<span><strong>${h(name)}</strong><small>${h(desc)}</small></span>${icon('chevron','v15-chevron')}</button>`).join('')}</div></section>`).join('')}</div>`;}
function fundPicker(a,selected){return `<label class="v15-fund-picker"><span>所持基金</span><select id="v7-analysis-fund">${a.funds.map(f=>`<option value="${h(f.id)}" ${f.id===selected?'selected':''}>${h(f.name)} · ${h(f.code)}</option>`).join('')}</select></label>`;}
const line=(title,content)=>`<div class="v15-reading"><h3>${h(title)}</h3>${content}</div>`;
function bar(label,value,max=1,extra=''){return `<div class="v15-bar-row"><span>${h(label)}</span><div class="v15-bar-track"><i style="width:${Math.max(0,Math.min(100,100*value/(max||1)))}%"></i></div><strong>${h(extra||p(value))}</strong></div>`;}
export function overlapView(a,ui){
 const A=a.funds.find(x=>x.id===ui.overlapA)||a.funds[0],B=a.funds.find(x=>x.id===ui.overlapB&&x.id!==A.id)||a.funds.find(x=>x.id!==A.id),pair=pairOverlap(A,B),whole=a.portfolioOverlap,mode=ui.overlapMode==='pair'?'pair':'portfolio',r=mode==='pair'?pair:whole;
 const select=(id,selected,exclude)=>`<select id="${id}">${a.funds.map(f=>`<option value="${h(f.id)}" ${f.id===selected?'selected':''} ${f.id===exclude?'disabled':''}>${h(f.name)} · ${h(f.code)}</option>`).join('')}</select>`;
 const rail=`<aside class="v15-compare-rail"><h3>两基金比较</h3><label>基金A${select('overlap-fund-a',A.id,B?.id)}</label><label>基金B${select('overlap-fund-b',B?.id,A.id)}</label>${button('overlap-mode','比较这两只','pair')}<div class="v15-source-date">${icon('calendar')}<span>${h(r.asOf||'按同期披露比较')}<small>股票占基金净资产</small></span></div></aside>`;
 let body;if(!r.ready)body=empty(r.reason,`<a class="v15-text-link" href="#holdings">管理持仓 ${icon('arrow')}</a>`);
 else if(mode==='pair')body=`<div class="v15-stat-band">${metric('股票重叠度',p(pair.value))}${metric('共同持股',pair.common+' 只')}${metric('双边匹配金额',money(pair.amount))}</div><div class="v15-table-wrap"><table class="v15-table"><thead><tr><th>共同持有的股票</th><th>${h(A.name)}</th><th>${h(B.name)}</th></tr></thead><tbody>${pair.rows.slice(0,30).map(x=>`<tr><td><strong>${h(x.name)}</strong><small>${h(x.code)}</small></td><td>${bar('',x.aWeight,.15)}</td><td>${bar('',x.bWeight,.15)}</td></tr>`).join('')}</tbody></table>${pair.rows.length>30?`<details class="v15-more"><summary>查看其余 ${pair.rows.length-30} 只股票</summary><table class="v15-table"><tbody>${pair.rows.slice(30).map(x=>`<tr><td>${h(x.name)} · ${h(x.code)}</td><td>${p(x.aWeight)}</td><td>${p(x.bWeight)}</td></tr>`).join('')}</tbody></table></details>`:''}</div>`;
 else body=`<div class="v15-stat-band">${metric('共同持股',whole.common+' 只')}${metric('共同持有的组合占比',p(whole.sharedExposure))}${metric('重复路径占比',p(whole.duplicateExposure))}</div><div class="v15-scope-line">本次 ${whole.includedFunds} / ${whole.totalFunds} 只基金 · 已展开组合 ${p(whole.coverage)} · ${whole.asOf}</div><div class="v15-table-wrap"><table class="v15-table"><thead><tr><th>共同持有的股票</th><th>持有基金</th><th>合计占组合</th><th>重复路径占比</th></tr></thead><tbody>${whole.rows.slice(0,20).map(x=>`<tr><td><strong>${h(x.name)}</strong><small>${h(x.code)}</small></td><td><details class="v15-paths"><summary>${x.count} 只</summary>${x.paths.map(f=>`<p>${h(f.name)}<span>${p(f.weight)}</span></p>`).join('')}</details></td><td>${p(x.weight)}</td><td>${p(x.duplicate)}</td></tr>`).join('')||'<tr><td colspan="4">当前同期披露未发现共同持股</td></tr>'}</tbody></table>${whole.rows.length>20?`<details class="v15-more"><summary>查看其余 ${whole.rows.length-20} 只</summary><table class="v15-table"><tbody>${whole.rows.slice(20).map(x=>`<tr><td>${h(x.name)} · ${h(x.code)}</td><td>${x.count}只</td><td>${p(x.weight)}</td><td>${p(x.duplicate)}</td></tr>`).join('')}</tbody></table></details>`:''}</div>`;
 if(mode==='pair'&&pair.ready)body+=`<details class="v15-more"><summary>匹配敞口的年费估算</summary><p>${money(pair.feeEstimate)} / 年 · ${h(pair.feeBasis)}</p><p>把可比年费归属到这部分持有路径，便于看清费用组成。</p></details>`;
 return `<div class="v15-detail-tools"><div class="v15-segments" aria-label="重叠比较范围">${button('overlap-mode','整个组合','portfolio',mode==='portfolio')}${button('overlap-mode','两只基金','pair',mode==='pair')}</div><span>${h(r.asOf||'同期披露')}</span></div><div class="v15-comparison">${rail}<div class="v15-comparison-data">${body}</div></div>${formula('两基金重叠度=Σmin(股票占基金A净资产比例，股票占基金B净资产比例)。双边匹配金额=2Σmin(A持有金额×股票比例，B持有金额×股票比例)。组合共同持有占比，把由两只及以上基金持有的股票按组合权重加总；重复路径占比=Σ(该股票组合占比−最大单基金路径占比)。敞口年费估算=双边匹配金额/2×两基金可比年费率之和，是费用归属测算。这些数值使用同一期半年度或年度已收录股票，不把各基金对的重叠相加。')}`;
}
function diversificationView(a){const s=a.structure;if(!s.ready)return empty(s.reason);return `<div class="v15-stat-band">${metric('名义持股数',s.nominal+' 只')}${metric('有效持股数',s.effective.toFixed(1)+' 只')}${metric('名义／有效',s.multiple.toFixed(2)+' 倍')}</div><p class="v15-key-sentence">已披露的 ${s.nominal} 只股票，按权重折算相当于 <strong>${s.effective.toFixed(1)} 只</strong>等权股票。</p><div class="v15-two-columns"><div class="v15-reading"><h3>数量与权重</h3>${bar('名义持股',s.nominal,s.nominal,s.nominal+'只')}${bar('有效持股',s.effective,s.nominal,s.effective.toFixed(1)+'只')}<small>${h(s.asOf)} · 已展开 ${p(s.coverage)}</small></div><div class="v15-reading"><h3>占比靠前的股票</h3>${s.rows.slice(0,8).map(x=>bar(x.name,x.weight,Math.max(s.rows[0]?.weight||1,.01))).join('')}</div></div>${formula('名义持股数按证券代码去重。先在已展开的股票中归一化权重p，再计算有效持股数=1/Σp²。有效持股越接近名义数量，权重越均匀；名义／有效倍数越大，权重越集中。已展开比例至少50%时展示。')}`;}
function riskView(a){const r=a.risk;if(!r.ready)return empty(r.reason);return `<div class="v15-scope-line">${r.from} 至 ${r.to} · ${r.n} 个日收益</div><div class="v15-chart-legend"><span>资金占比</span><span>波动贡献</span></div><div class="v15-risk-list">${r.deviations.map(x=>`<div><strong>${h(x.name)}</strong><div>${bar('资金',x.weight,1)}${bar('波动',Math.abs(x.riskShare||0),1,p(x.riskShare))}</div><span class="v15-delta">${Number.isFinite(x.deviation)?(100*x.deviation).toFixed(2)+' 个百分点':'—'}</span></div>`).join('')}</div>${formula('资金占比是基金金额占组合总额的比例。波动贡献份额=wᵢ(Σw)ᵢ/(wᵀΣw)，其中Σ是共同日收益的样本协方差矩阵。偏离=波动贡献份额−资金占比。负贡献表示该基金在这段历史中抵消了部分组合波动。')}`;}
function managerView(a){return `<div class="v15-two-columns">${line('共同的基金经理',a.managers.length?a.managers.map(x=>`<div class="v15-person"><span>${icon('people')}</span><div><h4>${h(x.name)}</h4><p>${x.funds.map(f=>h(f.name)).join('、')}</p></div></div>`).join(''):empty('当前所持基金的基金经理各不相同'))}${line('所持基金的经理',a.funds.map(f=>`<div class="v15-manager-row"><strong>${h(f.name)}</strong><span>${(f.managerDetails||[]).map(m=>h(m.name)).join('、')||'经理资料待更新'}</span><small>${(f.managerDetails||[]).map(m=>`${h(m.name)}关联${m.count}个基金代码`).join(' · ')}</small></div>`).join(''))}</div><details class="v15-more"><summary>经理变更公告</summary>${a.funds.flatMap(f=>(f.managerChanges||[]).map(x=>`<p>${x.date} · ${h(f.name)}<br><a class="v15-text-link" href="${h(x.url)}" target="_blank" rel="noopener noreferrer">${h(x.title)}</a></p>`)).join('')||'<p>当前收录窗口中暂无经理变更公告。</p>'}</details>${formula('经理关联按同一管理人下的同名经理匹配；主档关联代码数包含不同份额与历史记录。选择“经理变更公告”可查看已收录的任职调整。','如何阅读经理关联')}`;}
function navChart(points,showValues=true){if(!points?.length)return '';const rows=points.map(p=>Array.isArray(p)?p:[p.date,p.value]),base=rows[0][1],values=rows.map(p=>p[1]/base-1),lo=Math.min(0,...values),hi=Math.max(.01,...values),w=900,H=240,step=Math.max(1,Math.floor(rows.length/350)),sample=rows.map((p,i)=>({d:p[0],v:values[i],i})).filter((_,i)=>i%step===0||i===rows.length-1),xy=x=>`${(40+820*x.i/(rows.length-1||1)).toFixed(1)},${(20+180*(hi-x.v)/(hi-lo)).toFixed(1)}`,d=sample.map((x,i)=>(i?'L':'M')+xy(x)).join(' ');return `<figure class="v15-history-chart"><svg viewBox="0 0 ${w} ${H}" role="img" aria-label="${rows[0][0]}至${rows.at(-1)[0]}的${showValues?'区间收益':'净值观察'}走势"><title>历史净值走势</title>${[0,.5,1].map(t=>`<line x1="40" x2="860" y1="${20+180*t}" y2="${20+180*t}" stroke="currentColor" opacity=".08"/><text x="0" y="${24+180*t}">${showValues?p(hi-t*(hi-lo)):''}</text>`).join('')}<path d="${d}" fill="none" stroke="var(--soft-primary)" stroke-width="2.5"/><text x="40" y="235">${rows[0][0]}</text><text x="860" y="235" text-anchor="end">${rows.at(-1)[0]}</text></svg><figcaption>${showValues?'以区间起点为基准观察变化':'来源序列走势'}</figcaption></figure>`;}
function sourceTrend(a){const n=a.fund?.adjusted;if(!n||!['divergent'].includes(n.crossCheck)&&n.basis!=='acc-ratio')return '';const rows=(n.points||[]).filter(p=>p[0]<=a.asOf&&Number.isFinite(p[1])&&p[1]>0);return navChart(rows,false);}
function drawdownView(a,ui){const portfolio=ui.historyScope!=='fund',r=portfolio?a.risk.path:a.fund.metrics,ready=portfolio?a.risk.ready:r?.ready;return `<div class="v15-detail-tools"><div class="v15-segments">${button('history-scope','整个组合','portfolio',portfolio)}${button('history-scope','单只基金','fund',!portfolio)}</div>${!portfolio?fundPicker(a,a.fund.id):''}</div>${!ready?empty(portfolio?a.risk.reason:r?.reason||'净值历史待更新')+(!portfolio?sourceTrend(a):''):`<div class="v15-stat-band">${metric('最大回撤',p(r.maxDrawdown))}${metric('恢复情况',r.recoveryDays===null?'尚未恢复':r.recoveryDays+' 天')}${metric('前高至低点',r.peakDate+' → '+r.troughDate)}</div><p class="v15-scope-line">按当前${portfolio?'组合':'基金'}金额折算的历史回撤金额 ${money((portfolio?a.funds.reduce((s,f)=>s+f.amount,0):a.fund.amount)*r.maxDrawdown)}${r.recoveryDate?' · 恢复日 '+r.recoveryDate:''}</p>${!portfolio&&a.fund.peer?.medianDrawdown!==null&&a.fund.peer?.medianDrawdown!==undefined?`<div class="v15-reading"><h3>同期同类对照</h3><p>本基金 ${p(a.fund.peer.targetDrawdown)} · 同类中位数 ${p(a.fund.peer.medianDrawdown)}</p><small>${h(a.fund.peer.from)} 至 ${h(a.fund.peer.to)} · ${a.fund.peer.returnSamples} 个代码</small></div>`:''}${navChart(portfolio?a.risk.path.points:a.checked.points)}<div class="v15-scope-line">${portfolio?a.risk.from:r.from} 至 ${portfolio?a.risk.to:r.to} · 来源净值计算</div>`}${formula('回撤=1−当前价值/此前最高价值。最大回撤是区间里最大的回落幅度；恢复天数从低点算到首次重新达到此前高点。组合以当前权重在起点投入，期间基金之间不调仓。')}`;}
function experienceView(a){const f=a.fund,m=f.metrics;if(!m?.ready)return fundPicker(a,f.id)+empty(m?.reason||'净值历史待更新')+sourceTrend(a);return `${fundPicker(a,f.id)}<div class="v15-stat-band">${metric('区间收益',p(m.totalReturn))}${metric('正收益日占比',p(m.positiveDayRatio))}${metric('回撤恢复效率',Number.isFinite(m.recoveryEfficiency)?p(m.recoveryEfficiency)+' / 交易日':m.recoveryDays===null?'尚未恢复':'—')}</div>${navChart(a.checked.points)}<p class="v15-scope-line">${m.from} 至 ${m.to} · ${m.n} 个有效日收益${m.tradingRecovery!==null?' · 恢复用了 '+m.tradingRecovery+' 个交易日':''}</p><div class="v15-two-columns">${line('这段历史里的上涨日',`<p><strong>${p(m.positiveDayRatio)}</strong> 的有效日收益大于0。</p><small>${m.from} 至 ${m.to}</small>`)}${line('恢复到此前高点',`<p>${m.recoveryDate?'低点后 '+m.recoveryDays+' 个自然日，恢复于 '+m.recoveryDate:'截至 '+m.to+'，尚未恢复至 '+m.peakDate+' 的高点。'}</p>`)}</div><details class="v15-more"><summary>观察历史下跌日的影响</summary><p>将最差20个日收益设为0，区间收益变为 <strong>${p(m.returnExWorst20)}</strong>。</p><small>这是对已发生日期的事后敏感性计算。</small></details>${formula('区间收益=期末复权观察值/期初值−1。正收益日占比=日收益大于0的天数/有效日收益总天数，零收益日计入分母。恢复效率=最大回撤幅度/从低点恢复到前高的交易日数。')}`;}
function feeView(a){const f=a.fund,r=f.feeCompare;return `${fundPicker(a,f.id)}${!r?.ready?empty(r?.reason||'费率资料待更新'):`<div class="v15-stat-band">${metric('来源年费率',p(r.value))}${metric('同组最低费率',p(r.minimum))}${metric('对应年费差额',money(f.amount*r.differenceRate))}</div><p class="v15-scope-line">${h(r.components)} · ${h(r.basis)} · ${r.n} 个代码</p><p class="v15-scope-line">费率低于本基金的样本占 ${p(r.percentile)} · 从低到高并列第 ${r.rank} / ${r.n} 位</p><div class="v15-table-wrap"><table class="v15-table"><thead><tr><th>部分可比基金</th><th>年费率</th></tr></thead><tbody>${r.items.map(x=>`<tr><td>${h(x.name)}<small>${x.code}</small></td><td>${bar('',x.rate,Math.max(...r.items.map(v=>v.rate),.001))}</td></tr>`).join('')}</tbody></table></div>`}${formula('先比较同指数、同类型、同产品形式的基金，再比较同类型与规模档。按共同已知的费用项目计算，年费差额=当前持有金额×(本基金费率−组内最低费率)。计算针对管理、托管及已知销售服务费；交易与申赎费用另行计算。')}`;}
function peersView(a){const f=a.fund,q=f.peerR2,s=f.peerScore;return `${fundPicker(a,f.id)}<div class="v15-stat-band">${metric('同类走势相似度 R²',q?.ready&&Number.isFinite(q.value)?q.value.toFixed(3):'待更新',q?.ready?q.n+'个其他同类 · '+q.observations+'日':'')}${metric('加权统计分',s?.ready?s.score.toFixed(1)+' / 100':'待更新')}${metric('同口径评分分位',p(s?.percentile),s?.comparableCount?s.comparableCount+'个代码':'')}</div><div class="v15-factor-list">${(s?.factors||[]).map(x=>`<div><span>${h(x.name)}<small>${x.ready?'权重 '+(100*x.weight).toFixed(1)+'%':'资料待更新'}</small></span>${x.ready?`<div class="v15-bar-track"><i style="width:${x.score}%"></i></div><strong>${x.score.toFixed(1)}</strong>`:'<span>—</span>'}</div>`).join('')}</div><div class="v15-scope-line">${q?.from||f.peer?.from||''} 至 ${q?.to||f.peer?.to||''} · 同类型与规模档</div>${formula('R²描述本基金与其他同类等权均值的走势关联，均值剔除本基金。六项统计采用试验权重：成本25%、下行25%、正收益日20%、排名稳定15%、规模位置10%、持仓权重变化5%；可用项目重新归一。同口径评分分位只在可用因子一致的组内计算。')}`;}
function changesView(a){const f=a.fund,t=f.trend;return `${fundPicker(a,f.id)}${t?.ready?`<div class="v15-stat-band">${metric('此前集中度',t.previous.hhi.toFixed(4),t.from)}${metric('最新集中度',t.current.hhi.toFixed(4),t.to)}${metric('权重变化距离',t.cosineDistance.toFixed(4))}</div><p class="v15-key-sentence">已披露股票权重${t.delta>0?'更集中':t.delta<0?'更均匀':'集中度相同'}。</p>`:empty('收录两期半年度或年度明细后，可在这里对照变化')}<div class="v15-reading"><h3>净值历史覆盖</h3>${outsideSample(f.profile||f,a.checked).map(x=>`<div class="v15-range-row"><strong>${x.label}</strong><span>${h(x.reason)}</span></div>`).join('')}</div>${formula('集中度HHI=Σp²，p为已展开股票内部的归一权重；权重变化距离=1−cos(wₜ,wₜ₋₁)。两期均使用半年度或年度明细，避免混用季度前列股票。权重变化包含价格、申赎和交易的共同影响。')}`;}
function aiPanel(ui,module){return `<section class="v15-ai-panel ${ui.analysisAIOpen?'':'is-collapsed'}" id="analysis-ai" aria-label="AI解读"><div class="v15-ai-panel-head">${icon('spark')}<h2>AI解读</h2><span>${h(module[1])}</span></div><form id="v15-analysis-ai-form"><div class="v15-ai-presets">${button('analysis-preset','解读当前模块','analysis_module')}${button('analysis-preset','整体看组合','analysis_overview')}${button('analysis-preset','费用与同类','analysis_cost')}${button('analysis-preset','历史体验','analysis_history')}</div><label class="v15-question"><input name="question" maxlength="2000" placeholder="也可以写下你想了解的问题" value="${h(ui.analysisQuestion||'')}" aria-label="持仓分析提问"><button type="submit" class="v15-send" aria-label="发送分析问题">${icon('arrow')}</button></label></form><div class="v15-ai-status" data-ai-scope="analysis" aria-live="polite"></div></section>`;}
export function renderAnalysisV15(model,bounds,data,ui={}){
 const selected=moduleById(ui.analysisModule||'overlap'),head=`<div class="v15-pagehead"><div><h1>持仓分析</h1><span>当前组合 · ${model.funds.length}只基金</span></div><button type="button" class="v15-primary" data-act="toggle-analysis-ai">${icon('spark')}AI解读</button></div>`,directory=moduleDirectory(selected[0]);
 if(!model.funds.length)return head+directory+empty('添加基金和持有金额，开始查看组合。',button('edit-holdings','添加持仓'));
 if(!data?.manifest)return head+directory+empty('正在读取组合资料…');
 const a=analysisData(model,data,ui.analysisFund),views={overlap:()=>overlapView(a,ui),diversification:()=>diversificationView(a),managers:()=>managerView(a),risk:()=>riskView(a),drawdown:()=>drawdownView(a,ui),experience:()=>experienceView(a),fees:()=>feeView(a),peers:()=>peersView(a),changes:()=>changesView(a)};
 return head+directory+aiPanel(ui,selected)+`<section class="v15-detail" id="analysis-detail" aria-label="${h(selected[1])}"><header class="v15-workspace-head"><div>${icon(selected[2])}<h2>${h(selected[1])}</h2></div><button class="v15-text-link" type="button" data-act="analysis-directory">分析目录 ${icon('arrow')}</button></header>${views[selected[0]]()}</section><details class="v15-boundaries"><summary>个人关注线 ${icon('down')}</summary><form id="bounds-form" class="v8-inline-form">${[['fund','单只基金（%）'],['company','单只股票（%）'],['loss','关注金额（元）'],['horizon','持有期（月）']].map(([key,label])=>`<label>${label}<input name="${key}" type="number" min="0" value="${bounds[key]??''}"></label>`).join('')}<button class="v15-button">保存</button></form></details>`;
}
